class PndPidCorrelator : public FairTask {
 public:
  virtual void Exec(Option_t *option);
  virtual InitStatus Init();

  void Register();
  void Reset();

  PndPidCorrelator(const char *name, const char *title = "Pnd Task",
                   Bool_t use_default_setup = kTRUE);                 ///< Constrcutor setting name and title.
  PndPidCorrelator(Bool_t use_default_setup = kTRUE);                 ///< Default constructor.
  virtual ~PndPidCorrelator();                                        ///< Default destructor.

  void SetOption(Option_t *option = " ")
  {
    fOption = option;
    fOption.ToLower();
  }
  void SetDebugMode(Bool_t debug) { fDebugMode = debug; };
  void SetDebugFilename(TString filename) { fDebugFile = filename; };
  void SetMdtRefit(Bool_t mdt) { fMdtRefit = mdt; };
  void SetTrackBranch(TString branch) { fTrackBranch = branch; };
  void SetOutputBranch(TString branch) { fTrackOutBranch = branch; };

  void SetIdeal(Bool_t id) { fIdeal = id; };
  void SetFast(Bool_t fast) { fFast = fast; };
  void SetCorrErrProp(Bool_t err) { fCorrErrorProp = err; };
  void SetPidHyp(Int_t pid) { fPidHyp = pid; };
  void SetIdealHyp(Bool_t opt = kTRUE) { fIdealHyp = opt; }
  void SetFlagCut(Bool_t opt = kTRUE) { fFlagCut = opt; };
  void SetBackPropagate(Bool_t opt = kTRUE) { fBackPropagate = opt; };

  void SetUsePropagator(Bool_t use_propagator = kTRUE) { fUsePropagator = use_propagator; };
  
  /**
   * @brief Set propagator for all necessary propagation of tracks.
   * @param propagator Propagator to be used.
   */
  void SetPropagator(PndPropagator* propagator = nullptr);

  void SetCalorimeterInfo(PndPidCalorimeterInfo *detector_info);
  void SetBarrelDetectors(std::vector<PndPidDetectorInfo *> barrel_detectors);
  void AddBarrelDetector(PndPidDetectorInfo *detector_info);
  void SetForwardDetectors(std::vector<PndPidDetectorInfo *> forward_detectors);
  void AddForwardDetector(PndPidDetectorInfo *detector_info);
  void SetTrackingSystemInfo(PndPidTrackingSystemInfo *tracking_info);
  void SetTrackingDetectors(std::vector<PndPidTrackingDetectorInfo *> tracking_detectors);
  void AddTrackingDetector(PndPidTrackingDetectorInfo *detector_info);

  virtual void SetParContainers();
  virtual void Finish();

 protected:
  TClonesArray *fPidChargedCand = nullptr;       ///< PndPidCandidate TCA for charged particles
  TClonesArray *fPidNeutralCand = nullptr;       ///< PndPidCandidate TCA for neutral particles

  std::map <Int_t, PndPidCandidate *> fCandidateBuffer;

  PndPidCorrPar *fCorrPar = new PndPidCorrPar(); ///< Correlation parameters
  FairRootManager *fManager = FairRootManager::Instance();

  TString fTrackBranch = "";                     ///< Options to choose PndTrack branches
  TString fTrackOutBranch = "";                  ///< Options to choose output branch

  Int_t fPidHyp = 0;                             ///< particle hypothesis for propagation
  Bool_t fIdeal = kFALSE;                        ///< Ideal Correlation
  Bool_t fIdealHyp = kFALSE;                     ///< Flag to use MC particle hypothesis
  Bool_t fDoNeutralCand = kFALSE;                ///< Create neutral candidates
  Bool_t fFast = kFALSE;                         ///< kFALSE: normal; kTRUE: no correlation/extrapolation/neutral
  Bool_t fFlagCut = kFALSE;                      ///< kFALSE: all the tracks; kTRUE: store tracks only if flag>0
  Bool_t fMdtRefit = kFALSE;                     ///< Use MDT Kalman refit propagation
  Bool_t fCorrErrorProp = kTRUE;                 ///< Error propagation in correlation

  Bool_t fDebugMode = kFALSE;                    ///< If true fill ntuples for debug
  TString fDebugDir = "";                        ///< Ntuple output directory
  TString fDebugFile = "";                       ///< Ntuple output file
  TFile *fFileDebugNtuples = nullptr;           ///< File for debug ntuples

