std::shared_ptr<Model1D> PndLmdModelFactory::generate1DVertexModel(
    const boost::property_tree::ptree &model_opt_ptree) const {
  std::shared_ptr<Model1D> vertex_model;

  LumiFit::ModelType model_type(LumiFit::StringToModelType.at(
      model_opt_ptree.get<std::string>("model_type")));

  if (model_type == LumiFit::UNIFORM) {
    vertex_model.reset(new DoubleGaussianModel1D("vertex_double_gaussian_1d"));
  } else if (model_type == LumiFit::GAUSSIAN) {
    vertex_model.reset(new GaussianModel1D("vertex_gaussian_1d"));
  } else {
    std::cout
        << "Unknown vertex model! Only uniform and gaussian model is allowed."
        << std::endl;
  }

  return vertex_model;
}

std::shared_ptr<Model> PndLmdModelFactory::generateModel(
    const boost::property_tree::ptree &model_opt_ptree,
    const PndLmdAngularData &data) const {
  std::shared_ptr<Model> current_model;

  std::cout << "Generating model ... " << std::endl;

  unsigned int fit_dimension =
      model_opt_ptree.get<unsigned int>("fit_dimension");
  if (fit_dimension == 1) {
    current_model = generate1DModel(model_opt_ptree, data);
  } else if (fit_dimension == 2) {
    current_model = generate2DModel(model_opt_ptree, data);
  } else {
    std::cout << "WARNING: Requesting a model of dimension " << fit_dimension
              << " which is NOT available! Returning NULL pointer."
              << std::endl;
  }
  return current_model;
}

void runLmdFit(string input_file_dir, string fit_config_path,
               string acceptance_file_dir, string reference_acceptance_file_dir,
               unsigned int nthreads, string lumiFitResultPath,
               string recoIPfile) {

  boost::chrono::thread_clock::time_point start =
      boost::chrono::thread_clock::now();

  PndLmdRuntimeConfiguration &lmd_runtime_config =
      PndLmdRuntimeConfiguration::Instance();
  lmd_runtime_config.setNumberOfThreads(nthreads);
  lmd_runtime_config.setGeneralConfigDirectory(fit_config_path);

  // TODO: why is the file name hard coded?
  lmd_runtime_config.readAcceptanceOffsetTransformationParameters(
      "offset_trafo_matrix.json");

  lmd_runtime_config.setElasticDataInputDirectory(input_file_dir);
  lmd_runtime_config.setAcceptanceResolutionInputDirectory(acceptance_file_dir);
  lmd_runtime_config.setReferenceAcceptanceResolutionInputDirectory(
      reference_acceptance_file_dir);

  lmd_runtime_config.setElasticDataName("lmd_data_.*of.*.root");
  lmd_runtime_config.setAccDataName("lmd_acc_data_.*of1.root");
  lmd_runtime_config.setResDataName("lmd_res_data_.*of1.root");
  lmd_runtime_config.setVertexDataName("lmd_vertex_data_.*of1.root");

  // ============================== read data ============================== //

  // get lmd data and objects from files
  PndLmdDataFacade lmd_data_facade;

  PndLmdFitFacade lmd_fit_facade;

  // get vertex data and determine and run ip determination for these
  vector<PndLmdHistogramData> my_vertex_vec = lmd_data_facade.getVertexData();
  // do fits

  // TODO: why is the file name hard coded?
  lmd_runtime_config.readFitConfig("vertex_fitconfig.json");
  lmd_fit_facade.fitVertexData(my_vertex_vec);

  // read reco IP from file
  std::pair<double, double> ip_offsets(0.0, 0.0);
  if (recoIPfile == "") {
    std::cout << "WARNING: no reco IP file given, using 0,0 as reco IP\n";
  } else {
    std::cout << "reading reco IP from file: " << recoIPfile << "\n";
    boost::property_tree::ptree reco_ip_ptree;
    read_json(recoIPfile, reco_ip_ptree);
    double reco_ip_x = reco_ip_ptree.get<double>("ip_x");
    double reco_ip_y = reco_ip_ptree.get<double>("ip_y");
    ip_offsets.first = reco_ip_x;
    ip_offsets.second = reco_ip_y;
  }
  // print them just to be sure
  std::cout << "Read reco IP values " << ip_offsets.first << " and "
            << ip_offsets.second << "\n";

  // ok now we have to set the correct ip offsets to the elastic data sets
  // so compare the data on an abstract level
  vector<PndLmdAngularData> all_lmd_data_vec = lmd_data_facade.getElasticData();
  for (auto &data : all_lmd_data_vec) {
    data.setIPOffsets(ip_offsets);
  }

  lmd_runtime_config.readFitConfig(fit_config_path);

  // filter out specific data
  LumiFit::LmdDimensionOptions lmd_dim_opt;
  lmd_dim_opt.dimension_type = LumiFit::THETA_X;
  lmd_dim_opt.track_type = LumiFit::MC;

  const boost::property_tree::ptree &fit_config_ptree =
      lmd_runtime_config.getFitConfigTree();
  if (fit_config_ptree.get<bool>(
          "fit.fit_model_options.acceptance_correction_active") == true) {
    lmd_dim_opt.track_type = LumiFit::MC_ACC;
    if (fit_config_ptree.get<bool>(
            "fit.fit_model_options.resolution_smearing_active") == true)
      lmd_dim_opt.track_type = LumiFit::RECO;
  }

  LumiFit::Comparisons::DataPrimaryDimensionOptionsFilter filter(lmd_dim_opt);
  vector<PndLmdAngularData> my_lmd_data_vec =
      lmd_data_facade.filterData<PndLmdAngularData>(all_lmd_data_vec, filter);

  LumiFit::Comparisons::NoSecondaryTrackFilter no_cut_on_secondary_filter;
  my_lmd_data_vec = lmd_data_facade.filterData<PndLmdAngularData>(
      my_lmd_data_vec, no_cut_on_secondary_filter);

/*
 * This is the application that generates the Lmd data objects, which can be
 * used to determine the luminosity. This application primarily uses the
 * #PndLmdDataFacade class to easily create lmd fit data objects and fill them
 * with data. General information about the individual classes of the LmdFit
 * framework can be found in the doxygen manual.
 * Run it with argument -h to get running help:
 *
 * ./createLumiFitData -h
 */

#include "ui/PndLmdDataFacade.h"
#include "ui/PndLmdRuntimeConfiguration.h"

#include <iostream>
#include <string>

using std::cerr;
using std::cout;
using std::endl;
using std::string;

void createLmdFitData(const std::string &input_dir_path,
                      const std::string &filelist_path,
                      const std::string &output_dir_path,
                      const std::string &config_file_url, const double mom,
                      std::string &data_types, int num_events,
                      const double total_elastic_cross_section) {
  std::cout << "Running LmdFit data reader....\n";

  PndLmdRuntimeConfiguration &lmd_runtime_config =
      PndLmdRuntimeConfiguration::Instance();

  // set paths and general infos first
  lmd_runtime_config.setMomentum(mom);
  lmd_runtime_config.setNumEvents(num_events);
  lmd_runtime_config.setTotalElasticCrossSection(total_elastic_cross_section);

  lmd_runtime_config.setRawDataDirectory(input_dir_path);
  if (filelist_path != "")
    lmd_runtime_config.setRawDataFilelistPath(filelist_path);
  lmd_runtime_config.setDataOutputDirectory(output_dir_path);

  // set general config path
  lmd_runtime_config.setGeneralConfigDirectory(config_file_url);

  // read data parameter config
  boost::filesystem::path data_config_path(config_file_url);
  lmd_runtime_config.readDataConfig(data_config_path.filename().string());

  PndLmdDataFacade data_facade;

  PndLmdCombinedDataReader data_reader;
  if (!boost::filesystem::exists(lmd_runtime_config.getRawDataFilelistPath()))
    data_reader.addFilePath(lmd_runtime_config.getRawDataDirectory().string() +
                            "/Lumi_TrksQA*.root");
  else {
    data_reader.addFileList(
        lmd_runtime_config.getRawDataFilelistPath().string());
  }

  data_facade.createAndFillDataBundles(data_types, data_reader);

  std::cout << std::endl << std::endl;
  std::cout << "Application finished successfully." << std::endl;
  std::cout << std::endl;

  // ------------------------------------------------------------------------
}

void displayInfo() {
  // display info
  std::cout << "Required arguments are: " << std::endl;
  std::cout << "-m [pbar momentum]" << std::endl;
  std::cout << "-t [type of data to create] (a = angular, e = efficiency, r = "
               "resolution, v = vertex)"
            << std::endl;
  std::cout << "-d [input directory path]" << std::endl;
  std::cout << "-c [data config file path]" << std::endl;
  std::cout << "Optional arguments are: " << std::endl;
  std::cout << "-f [filelist path]" << std::endl;
  std::cout << "-o [output directory path]" << std::endl;
  std::cout << "-n [number of events to process] "
               "(default 0: all data found will be processed)"
            << std::endl;
  std::cout << "-e [total elastic cross section]" << std::endl;
  std::cout << std::endl;
  std::cout
      << "Note: The type value is specified as a string, in which the 4 "
         "letters\n"
         "a, e, r, v can be concatenated freely. For just a single data type\n"
         "the values should be a, e, r, v. For a combination i.e\n"
         "angular vertex data, one should use av or va. Other additional\n"
         "characters will be ignored, so can be specified without any effect!\n"
         "\n"
         "the parameter -e is the total elastic cross section to estimate\n"
         "the generated luminosity. In case you do NOT specify this value it\n"
         "will be set to -1.0 and there is no performance validation "
         "possible,\n"
         "but only luminosity determination. This should be the case only for\n"
         "real data!"
      << std::endl;
}

bool checkDataType(std::string &data_type) {
  bool is_valid = false;
  if (data_type.find("a") != std::string::npos) {
    is_valid = true;
  } else if (data_type.find("e") != std::string::npos) {
    is_valid = true;
  } else if (data_type.find("r") != std::string::npos) {
    is_valid = true;
  } else if (data_type.find("v") != std::string::npos) {
    is_valid = true;
  }
  return is_valid;
}

int main(int argc, char *argv[]) {
  bool is_mom_set = false, is_cross_section_set = false,
       is_data_path_set = false, is_filelist_path_set = false,
       is_output_data_path_set = false, is_config_file_path_set = false;
  double momentum = -1.0;
  std::string data_type = "";
  unsigned int num_events = 0;
  double cross_section = 1.0;
  std::string data_path;
  std::string config_file_path;
  std::string output_dir_path;
  std::string filelist_path("");
  int c;

  while ((c = getopt(argc, argv, "hm:f:o:n:t:d:c:e:")) != -1) {
    switch (c) {
    case 'm':
      momentum = atof(optarg);
      is_mom_set = true;
      break;
    case 'f':
      filelist_path = optarg;
      is_filelist_path_set = true;
      break;
    case 'o':
      output_dir_path = optarg;
      is_output_data_path_set = true;
      break;
    case 'n':
      num_events = atoi(optarg);
      break;
    case 'e':
      cross_section = atof(optarg);
      is_cross_section_set = true;
      break;
    case 't':
      data_type = optarg;
      break;
    case 'd':
      data_path = optarg;
      is_data_path_set = true;
      break;
    case 'c':
      config_file_path = optarg;
      is_config_file_path_set = true;
      break;
    case '?':
      if (optopt == 't' || optopt == 'd' || optopt == 'm' || optopt == 'n' ||
          optopt == 'c' || optopt == 'e')
        std::cerr << "Option -" << optopt << " requires an argument."
                  << std::endl;
      else if (isprint(optopt))
        std::cerr << "Unknown option -" << optopt << "." << std::endl;
      else
        std::cerr << "Unknown option character" << optopt << "." << std::endl;
      return 1;
    case 'h':
      displayInfo();
      return 1;
    default:
      return 1;
    }
  }

  bool skip_program = false;
  if (!is_output_data_path_set && is_filelist_path_set) {
    std::cerr << "Please specify an output directory via the -o option when "
                 "using a filelist path as input!"
              << std::endl;
    skip_program = true;
  }
  if (!(checkDataType(data_type) && is_mom_set && is_data_path_set))
    skip_program = true;

  if (skip_program)
    displayInfo();
  else {
    if (!is_output_data_path_set)
      output_dir_path = data_path;
    createLmdFitData(data_path, filelist_path, output_dir_path,
                     config_file_path, momentum, data_type, num_events,
                     cross_section);

    return 0;
  }
}

