void PndLmdDataReader::setBeam(double lab_momentum) {
  beam = TLorentzVector(
      0, 0, lab_momentum,
      sqrt(pow(lab_momentum, 2.0) + pow(pdg->GetParticle(-2212)->Mass(), 2.0)));
}

void PndLmdDataReader::read() {
  std::vector<PndLmdAbstractData *> lmd_vec = combineAllRegisteredDataObjects();

  if (0 == lmd_vec.size()) {
    std::cout << "No data or acceptance objects were registered, hence no data "
                 "can be filled."
                 " Please register objects via the register methods of this "
                 "helper class"
              << std::endl;
    return;
  }

  initDataStream();

  int temp_num_events = getEntries();
  int num_events = 0;

  // all data objects initialized with -1 as number of events
  // should be filled with all found data -> adjust that now
  for (unsigned int i = 0; i < lmd_vec.size(); i++) {
    if (0 == lmd_vec[i]->getNumEvents()) {
      lmd_vec[i]->setNumEvents(temp_num_events);
    }
  }

  // get maximum event number for all registered data objects
  for (unsigned int i = 0; i < lmd_vec.size(); i++) {
    if (num_events < lmd_vec[i]->getNumEvents())
      num_events = lmd_vec[i]->getNumEvents();
    else if (lmd_vec[i]->getNumEvents() == -1) {
      num_events = temp_num_events;
      break;
    }
    if (num_events > temp_num_events) {
      num_events = temp_num_events;
      break;
    }
  }
  // now run over all registered data objects once again and adjust
  // the number of events accordingly
  for (unsigned int i = 0; i < lmd_vec.size(); i++) {
    if (num_events < lmd_vec[i]->getNumEvents())
      lmd_vec[i]->setNumEvents(num_events);
    else if (lmd_vec[i]->getNumEvents() == -1) {
      lmd_vec[i]->setNumEvents(num_events);
    }
  }
  int min_num_events = getNextMinEventIndex(lmd_vec);

  std::cout << "Processing " << num_events << " events" << std::endl;

  boost::progress_display show_progress(num_events);

  for (Int_t j = 0; j < num_events; j++) {
    // this check is to remove the data registered data objects for which
    // the event count has reached the specified value
    if (j == min_num_events) {
      // remove the data objects that hit their specified event count
      removeFinished(lmd_vec, j);
      // adjust the minimum number of events to the remaining data objects
      min_num_events = getNextMinEventIndex(lmd_vec);
    }

    std::vector<Lmd::Data::TrackPairInfo> track_pair_infos = getEntry(j);
    for (auto const &trk_pair_info : track_pair_infos) {
      fillData(trk_pair_info);
    }
    ++show_progress;
  }

  cleanup();
}

void PndLmdDataReader::fillData(const Lmd::Data::TrackPairInfo &track_info) {
  if (isGoodTrack(track_info)) {
    std::vector<double> data(4);
    auto const &mom_mc = track_info.MCIP.Momentum;
    auto const &mom_rec = track_info.RecoIP.Momentum;
    data[0] = mom_rec[0] / mom_rec[2];
    data[1] = mom_rec[1] / mom_rec[2];
    data[2] = mom_mc[0] / mom_mc[2];
    data[3] = mom_mc[1] / mom_mc[2];

    for (unsigned int i = 0; i < registered_map_data.size(); ++i) {
      registered_map_data[i]->addData(data);
    }
  }

  for (unsigned int i = 0; i < registered_data.size(); i++) {
    if (!skipDataObject(registered_data[i], track_info)) {
      if (successfullyPassedFilters(registered_data[i], track_info)) {
        if (registered_data[i]->getSecondaryDimension().is_active) {
          registered_data[i]->addData(
              getTrackParameterValue(track_info,
                                     registered_data[i]->getPrimaryDimension()),
              getTrackParameterValue(
                  track_info, registered_data[i]->getSecondaryDimension()));
        } else {
          registered_data[i]->addData(getTrackParameterValue(
              track_info, registered_data[i]->getPrimaryDimension()));
        }
      }
    }
  }
  for (unsigned int i = 0; i < registered_acceptances.size(); i++) {
    bool track_accepted = wasReconstructed(track_info);
    if (track_info.IsSecondary) {
        continue;
    }
    // skip tracks that do not pass the filters
    if (successfullyPassedFilters(registered_acceptances[i], track_info)) {
      if (registered_acceptances[i]->getSecondaryDimension().is_active) {
        registered_acceptances[i]->addData(
            track_accepted,
            getTrackParameterValue(
                track_info, registered_acceptances[i]->getPrimaryDimension()),
            getTrackParameterValue(
                track_info,
                registered_acceptances[i]->getSecondaryDimension()));
      } else {
        registered_acceptances[i]->addData(
            track_accepted,
            getTrackParameterValue(
                track_info, registered_acceptances[i]->getPrimaryDimension()));
      }
    }
  }
}

bool PndLmdDataReader::isGoodTrack(
    const Lmd::Data::TrackPairInfo &track_info) const {
  return (track_info.IsReconstructedAtIP);
}

bool PndLmdDataReader::wasReconstructed(
    const Lmd::Data::TrackPairInfo &track_info) const {
  return (track_info.IsReconstructedAtIP);
}

bool PndLmdDataReader::skipDataObject(
    const PndLmdAbstractData *data,
    const Lmd::Data::TrackPairInfo &track_info) const {
  // if it was not reconstructed and this information is required
  if (!wasReconstructed(track_info)) {
    if (LumiFit::RECO ==
        data->getPrimaryDimension().dimension_options.track_type) {
      return true;
    } else if (LumiFit::MC_ACC ==
                   data->getPrimaryDimension().dimension_options.track_type ||
               LumiFit::DIFF_RECO_MC ==
                   data->getPrimaryDimension().dimension_options.track_type) {
      return true;
    }
    if (data->getSecondaryDimension().is_active) {
      if (LumiFit::RECO ==
          data->getSecondaryDimension().dimension_options.track_type)
        return true;
      else if (LumiFit::MC_ACC ==
                   data->getSecondaryDimension().dimension_options.track_type ||
               LumiFit::DIFF_RECO_MC ==
                   data->getSecondaryDimension().dimension_options.track_type) {
        return true;
      }
    }
  }
  if (LumiFit::MC == data->getPrimaryDimension().dimension_options.track_type) {
    if (track_info.IsSecondary)
      return true;
  }
  return false;
}

bool PndLmdDataReader::successfullyPassedFilters(
    const PndLmdAbstractData *data,
    const Lmd::Data::TrackPairInfo &track_info) const {
  // if it fails to pass a filter
  const std::set<LumiFit::LmdDimension> &selection_dimensions(
      data->getSelectorSet());
  std::set<LumiFit::LmdDimension>::iterator selection_dimension_iterator =
      selection_dimensions.begin();
  while (selection_dimension_iterator != selection_dimensions.end()) {
    if (false ==
        selection_dimension_iterator->dimension_range.isDataWithinRange(
            getTrackParameterValue(track_info,
                                   *selection_dimension_iterator))) {
      return false;
    }
    ++selection_dimension_iterator;
  }
  return true;
}

double PndLmdDataReader::getTrackParameterValue(
    const Lmd::Data::TrackPairInfo &track_info,
    const LumiFit::LmdDimension &lmd_dim) const {
  TVector3 pos(0.0, 0.0, 0.0);
  TVector3 mom(0.0, 0.0, 1.0);
  double theta(0.0);
  double phi(0.0);
  double theta_x(0.0);
  double theta_y(0.0);

  if (lmd_dim.dimension_options.dimension_type == LumiFit::PARTICLE_ID) {
    return 1.0 * track_info.PDGCode;
  }

  if (lmd_dim.dimension_options.dimension_type == LumiFit::SECONDARY) {
    return 1.0 * track_info.IsSecondary;
  }

  if (lmd_dim.dimension_options.track_type == LumiFit::MC ||
      lmd_dim.dimension_options.track_type == LumiFit::MC_ACC) {
    if (lmd_dim.dimension_options.track_param_type == LumiFit::IP) {
      auto mc_pos = track_info.MCIP.Position;
      pos.SetXYZ(mc_pos[0], mc_pos[1], mc_pos[2]);
      auto mc_mom = track_info.MCIP.Momentum;
      mom.SetXYZ(mc_mom[0], mc_mom[1], mc_mom[2]);
    } else if (lmd_dim.dimension_options.track_param_type == LumiFit::LMD) {
      auto mc_pos = track_info.MCLMD.Position;
      pos.SetXYZ(mc_pos[0], mc_pos[1], mc_pos[2]);
      auto mc_mom = track_info.MCLMD.Momentum;
      mom.SetXYZ(mc_mom[0], mc_mom[1], mc_mom[2]);
    }
    theta = mom.Theta();
    phi = mom.Phi();
    theta_x = mom.X() / mom.Z();
    theta_y = mom.Y() / mom.Z();
  } else if (lmd_dim.dimension_options.track_type == LumiFit::RECO) {
    if (lmd_dim.dimension_options.track_param_type == LumiFit::IP) {
      auto reco_pos = track_info.RecoIP.Position;
      pos.SetXYZ(reco_pos[0], reco_pos[1], reco_pos[2]);
      auto reco_mom = track_info.RecoIP.Momentum;
      mom.SetXYZ(reco_mom[0], reco_mom[1], reco_mom[2]);
    } else if (lmd_dim.dimension_options.track_param_type == LumiFit::LMD) {
      auto reco_pos = track_info.RecoLMD.Position;
      pos.SetXYZ(reco_pos[0], reco_pos[1], reco_pos[2]);
      auto reco_mom = track_info.RecoLMD.Momentum;
      mom.SetXYZ(reco_mom[0], reco_mom[1], reco_mom[2]);
    }
    theta = mom.Theta();
    phi = mom.Phi();
    theta_x = mom.X() / mom.Z();
    theta_y = mom.Y() / mom.Z();
  }

  else if (lmd_dim.dimension_options.track_type == LumiFit::DIFF_RECO_MC) {
    TVector3 mcpos(0.0, 0.0, 0.0);
    TVector3 mcmom(0.0, 0.0, 0.0);
    if (lmd_dim.dimension_options.track_param_type == LumiFit::IP) {
      auto mc_pos = track_info.MCIP.Position;
      mcpos.SetXYZ(mc_pos[0], mc_pos[1], mc_pos[2]);
      auto mc_mom = track_info.MCIP.Momentum;
      mcmom.SetXYZ(mc_mom[0], mc_mom[1], mc_mom[2]);
      auto reco_pos = track_info.RecoIP.Position;
      pos.SetXYZ(reco_pos[0], reco_pos[1], reco_pos[2]);
      auto reco_mom = track_info.RecoIP.Momentum;
      mom.SetXYZ(reco_mom[0], reco_mom[1], reco_mom[2]);
    } else if (lmd_dim.dimension_options.track_param_type == LumiFit::LMD) {
      auto mc_pos = track_info.MCLMD.Position;
      mcpos.SetXYZ(mc_pos[0], mc_pos[1], mc_pos[2]);
      auto mc_mom = track_info.MCLMD.Momentum;
      mcmom.SetXYZ(mc_mom[0], mc_mom[1], mc_mom[2]);
      auto reco_pos = track_info.RecoLMD.Position;
      pos.SetXYZ(reco_pos[0], reco_pos[1], reco_pos[2]);
      auto reco_mom = track_info.RecoLMD.Momentum;
      mom.SetXYZ(reco_mom[0], reco_mom[1], reco_mom[2]);
    }

    pos.SetXYZ(pos.X() - mcpos.X(), pos.Y() - mcpos.Y(), pos.Z() - mcpos.Z());
    theta = mom.Theta() - mcmom.Theta();
    phi = mom.Phi() - mcmom.Phi();
    if (phi > TMath::Pi())
      phi = phi - 2.0 * TMath::Pi();
    if (phi < TMath::Pi())
      phi = phi + 2.0 * TMath::Pi();

    theta_x = mom.X() / mom.Z() - mcmom.X() / mcmom.Z();
    theta_y = mom.Y() / mom.Z() - mcmom.Y() / mcmom.Z();
  }

  if (lmd_dim.dimension_options.dimension_type == LumiFit::X) {
    return pos.X();
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::Y) {
    return pos.Y();
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::Z) {
    return pos.Z();
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::T) {
    TLorentzVector track(mom, sqrt(pow(mom.Mag(), 2.0) +
                                   pow(pdg->GetParticle(-2212)->Mass(), 2.0)));
    return -(track - beam).M2();
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::THETA_X) {
    return theta_x;
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::THETA_Y) {
    return theta_y;
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::THETA) {
    return theta;
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::PHI) {
    return phi;
  } else
    return 0.0;
}

#include "data/PndLmdAngularData.h"
#include "ui/PndLmdDataFacade.h"
#include "ui/PndLmdFitFacade.h"
#include "ui/PndLmdPlotter.h"
#include "ui/PndLmdRuntimeConfiguration.h"

#include <iostream>
#include <string>

#define BOOST_CHRONO_HEADER_ONLY
#include <boost/chrono/thread_clock.hpp>
#include <boost/property_tree/json_parser.hpp>
#include <boost/property_tree/ptree.hpp>

#include "TFile.h"

using std::cerr;
using std::cout;
using std::endl;
using std::string;

void runLmdFit(string input_file_dir, string fit_config_path,
               string acceptance_file_dir, string reference_acceptance_file_dir,
               unsigned int nthreads, string lumiFitResultPath,
               string recoIPfile) {

  boost::chrono::thread_clock::time_point start =
      boost::chrono::thread_clock::now();

  PndLmdRuntimeConfiguration &lmd_runtime_config =
      PndLmdRuntimeConfiguration::Instance();
  lmd_runtime_config.setNumberOfThreads(nthreads);
  lmd_runtime_config.setGeneralConfigDirectory(fit_config_path);

  // TODO: why is the file name hard coded?
  lmd_runtime_config.readAcceptanceOffsetTransformationParameters(
      "offset_trafo_matrix.json");

  lmd_runtime_config.setElasticDataInputDirectory(input_file_dir);
  lmd_runtime_config.setAcceptanceResolutionInputDirectory(acceptance_file_dir);
  lmd_runtime_config.setReferenceAcceptanceResolutionInputDirectory(
      reference_acceptance_file_dir);

  lmd_runtime_config.setElasticDataName("lmd_data_.*of.*.root");
  lmd_runtime_config.setAccDataName("lmd_acc_data_.*of1.root");
  lmd_runtime_config.setResDataName("lmd_res_data_.*of1.root");
  lmd_runtime_config.setVertexDataName("lmd_vertex_data_.*of1.root");

  // ============================== read data ============================== //

  // get lmd data and objects from files
  PndLmdDataFacade lmd_data_facade;

  PndLmdFitFacade lmd_fit_facade;

  // get vertex data and determine and run ip determination for these
  vector<PndLmdHistogramData> my_vertex_vec = lmd_data_facade.getVertexData();
  // do fits

  // TODO: why is the file name hard coded?
  lmd_runtime_config.readFitConfig("vertex_fitconfig.json");
  lmd_fit_facade.fitVertexData(my_vertex_vec);

  // read reco IP from file
  std::pair<double, double> ip_offsets(0.0, 0.0);
  if (recoIPfile == "") {
    std::cout << "WARNING: no reco IP file given, using 0,0 as reco IP\n";
  } else {
    std::cout << "reading reco IP from file: " << recoIPfile << "\n";
    boost::property_tree::ptree reco_ip_ptree;
    read_json(recoIPfile, reco_ip_ptree);
    double reco_ip_x = reco_ip_ptree.get<double>("ip_x");
    double reco_ip_y = reco_ip_ptree.get<double>("ip_y");
    ip_offsets.first = reco_ip_x;
    ip_offsets.second = reco_ip_y;
  }
  // print them just to be sure
  std::cout << "Read reco IP values " << ip_offsets.first << " and "
            << ip_offsets.second << "\n";

  // ok now we have to set the correct ip offsets to the elastic data sets
  // so compare the data on an abstract level
  vector<PndLmdAngularData> all_lmd_data_vec = lmd_data_facade.getElasticData();
  for (auto &data : all_lmd_data_vec) {
    data.setIPOffsets(ip_offsets);
  }

  lmd_runtime_config.readFitConfig(fit_config_path);

  // filter out specific data
  LumiFit::LmdDimensionOptions lmd_dim_opt;
  lmd_dim_opt.dimension_type = LumiFit::THETA_X;
  lmd_dim_opt.track_type = LumiFit::MC;

  const boost::property_tree::ptree &fit_config_ptree =
      lmd_runtime_config.getFitConfigTree();
  if (fit_config_ptree.get<bool>(
          "fit.fit_model_options.acceptance_correction_active") == true) {
    lmd_dim_opt.track_type = LumiFit::MC_ACC;
    if (fit_config_ptree.get<bool>(
            "fit.fit_model_options.resolution_smearing_active") == true)
      lmd_dim_opt.track_type = LumiFit::RECO;
  }

  LumiFit::Comparisons::DataPrimaryDimensionOptionsFilter filter(lmd_dim_opt);
  vector<PndLmdAngularData> my_lmd_data_vec =
      lmd_data_facade.filterData<PndLmdAngularData>(all_lmd_data_vec, filter);

  LumiFit::Comparisons::NoSecondaryTrackFilter no_cut_on_secondary_filter;
  my_lmd_data_vec = lmd_data_facade.filterData<PndLmdAngularData>(
      my_lmd_data_vec, no_cut_on_secondary_filter);

  vector<PndLmdAcceptance> my_lmd_acc_vec = lmd_data_facade.getAcceptanceData();
  vector<PndLmdHistogramData> all_lmd_res = lmd_data_facade.getResolutionData();
  vector<PndLmdMapData> all_lmd_res_map = lmd_data_facade.getMapData();
  // ------------------------------------------------------------------------

  // start fitting
  // add acceptance data to pools
  // the corresponding acceptances to the data will automatically be taken
  // if not found then this fit is skipped
  lmd_fit_facade.addAcceptencesToPool(my_lmd_acc_vec);
  lmd_fit_facade.addResolutionsToPool(all_lmd_res);
  lmd_fit_facade.addResolutionMapsToPool(all_lmd_res_map);

  // we dont need these data objects anymore
  all_lmd_res_map.clear();
  my_lmd_acc_vec.clear();

  // do actual fits
  PndLmdFitDataBundle fit_result(
      lmd_fit_facade.doLuminosityFits(my_lmd_data_vec));

  // open file via runtime config and save results to file
  // create output file
  std::stringstream hs;
  hs << lmd_runtime_config.getElasticDataInputDirectory().string() << "/"
     << lmd_runtime_config.getFittedElasticDataName();

  fit_result.saveDataBundleToRootFile(hs.str());

  boost::chrono::thread_clock::time_point stop =
      boost::chrono::thread_clock::now();
  std::cout << "duration: "
            << boost::chrono::duration_cast<boost::chrono::milliseconds>(stop -
                                                                         start)
                       .count() /
                   60000.0
            << " min\n";

  // write data to json here

  //  This is surprisingly convoluted.

  // we want the fit Result
  // the stuff we're looking for is in a PndLmdElasticDataBundle
  // we have a PndLmdFitDataBundle, but that contains multiple
  // PndLmdElasticDataBundle
  // and these contain the actual fit_result s again

  auto elasticDataBundles = fit_result.getElasticDataBundles();

  // this code is copied from extractLuminosityvalues.cxx

  LumiFit::PndLmdPlotter lmd_plotter;

  // TODO: wait if there are multiple bundles, don't we also have multiple lumi
  // fits? what about the others?
  for (auto const &data_sample : elasticDataBundles) {
    if (data_sample.getFitResults().size() > 0 &&
        data_sample.getSelectorSet().size() == 0) {
      PndLmdLumiFitResult final_fit_result;
      for (auto const &fit_res_pair : data_sample.getFitResults()) {
        bool div_smeared =
            fit_res_pair.first.getModelOptionsPropertyTree().get<bool>(
                "divergence_smearing_active");
        for (auto const &fit_res : fit_res_pair.second) {
          // usually there is just a single fit result
          if (div_smeared) {
            if (fit_res.getFitStatus() == 0) {
              final_fit_result.setModelFitResult(fit_res);
              // break;
            }
          } else {
            final_fit_result.setModelFitResult(fit_res);
          }

          std::pair<double, double> lumi =
              lmd_plotter.calulateRelDiff(final_fit_result.getLuminosity(),
                                          final_fit_result.getLuminosityError(),
                                          data_sample.getReferenceLuminosity());

          std::cout << "Luminosity Fit Result:\n";
          std::cout << "measured luminosity:"
                    << final_fit_result.getLuminosity() << "\n";
          std::cout << "measured luminosity error:"
                    << final_fit_result.getLuminosityError() << "\n";
          std::cout << "generated luminosity:"
                    << data_sample.getReferenceLuminosity() << "\n";
          std::cout << "relative deviation (%):" << lumi.first << "\n";
          std::cout << "relative deviation error (%):" << lumi.second << "\n";

          // add this to json
          boost::property_tree::ptree lumiJson;
          lumiJson.put("measured_lumi", final_fit_result.getLuminosity());
          lumiJson.put("measured_lumi_error",
                       final_fit_result.getLuminosityError());
          lumiJson.put("generated_lumi", data_sample.getReferenceLuminosity());
          lumiJson.put("relative_deviation_in_percent", lumi.first);
          lumiJson.put("relative_deviation_error_in_percent", lumi.second);
          lumiJson.put("fit_converged",
                       final_fit_result.getModelFitResult().getFitStatus() ==
                           0);

          std::stringstream filename;
          if (lumiFitResultPath == "") {
            filename << input_file_dir;
            filename << "/lumi-values.json";
          } else {
            filename << lumiFitResultPath;
          }
          boost::property_tree::write_json(filename.str(), lumiJson);
        }
      }
    }
  }
}

void displayInfo() {
  // display info
  cout << "Required arguments are: " << endl;
  cout << "-d [abs path to data]" << endl;
  cout << "-c [abs path to fit config file]" << endl;
  cout << "Optional arguments are: " << endl;
  cout << "-m [number of threads]" << endl;
  cout << "-a [abs path to box gen data] (acceptance)" << endl;
  cout << "-r [abs path to reference box gen data] (acceptance)" << endl;
  cout << "-i [abs path to reco IP file]" << endl;
  cout << "-o [abs path to lumi fit result file]" << endl;
}

int main(int argc, char *argv[]) {
  string data_path;
  string acc_path("");
  string fit_config_path("");
  string ref_acc_path("");
  string lumiFitResultPath("");
  string recoIPfile("");

  unsigned int nthreads(1);
  bool is_data_set(false), is_config_set(false), is_acc_set(false),
      is_nthreads_set(false);

  int c;

  while ((c = getopt(argc, argv, "hc:a:m:r:d:X:Y:o:i:")) != -1) {
    switch (c) {
    case 'a':
      acc_path = optarg;
      is_acc_set = true;
      break;
    case 'c':
      fit_config_path = optarg;
      is_config_set = true;
      break;
    case 'r':
      ref_acc_path = optarg;
      break;
    case 'd':
      data_path = optarg;
      is_data_set = true;
      break;
    case 'm':
      nthreads = atoi(optarg);
      is_nthreads_set = true;
      break;
    case 'o':
      lumiFitResultPath = optarg;
      break;
    case 'i':
      recoIPfile = optarg;
      break;
    case '?':
      if (optopt == 'm' || optopt == 'd' || optopt == 'a' || optopt == 'c' ||
          optopt == 'r')
        cerr << "Option -" << optopt << " requires an argument." << endl;
      else if (isprint(optopt))
        cerr << "Unknown option -" << optopt << "." << endl;
      else
        cerr << "Unknown option character" << optopt << "." << endl;
      return 1;
    case 'h':
      displayInfo();
      return 1;
    default:
      return 1;
    }
  }

  if (is_data_set && is_config_set)
    runLmdFit(data_path, fit_config_path, acc_path, ref_acc_path, nthreads,
              lumiFitResultPath, recoIPfile);
  else
    displayInfo();
  return 0;
}

