    // std::cout << "smear weight: " << overall_smear << std::endl;
  }
  std::cout << "average mc bins per reco bin: "
            << 1.0 * average_contributors / temp_map.size() << std::endl;
  std::cout << "done!" << std::endl;

  // TVirtualPad *current_pad = gPad;
