class PndPidCorrelator : public FairTask {
 public:
  virtual void Exec(Option_t *option);
  virtual InitStatus Init();

  void Register();
  void Reset();

  PndPidCorrelator(const char *name, const char *title = "Pnd Task",
                   Bool_t use_default_setup = kTRUE);                 ///< Constrcutor setting name and title.
  PndPidCorrelator(Bool_t use_default_setup = kTRUE);                 ///< Default constructor.
  virtual ~PndPidCorrelator();                                        ///< Default destructor.

  void SetOption(Option_t *option = " ")
  {
    fOption = option;
    fOption.ToLower();
  }
  void SetDebugMode(Bool_t debug) { fDebugMode = debug; };
  void SetDebugFilename(TString filename) { fDebugFile = filename; };
  void SetMdtRefit(Bool_t mdt) { fMdtRefit = mdt; };
  void SetTrackBranch(TString branch) { fTrackBranch = branch; };
  void SetOutputBranch(TString branch) { fTrackOutBranch = branch; };

  void SetIdeal(Bool_t id) { fIdeal = id; };
  void SetFast(Bool_t fast) { fFast = fast; };
  void SetCorrErrProp(Bool_t err) { fCorrErrorProp = err; };
  void SetPidHyp(Int_t pid) { fPidHyp = pid; };
  void SetIdealHyp(Bool_t opt = kTRUE) { fIdealHyp = opt; }
  void SetFlagCut(Bool_t opt = kTRUE) { fFlagCut = opt; };
  void SetBackPropagate(Bool_t opt = kTRUE) { fBackPropagate = opt; };

  void SetUsePropagator(Bool_t use_propagator = kTRUE) { fUsePropagator = use_propagator; };
  
  /**
   * @brief Set propagator for all necessary propagation of tracks.
   * @param propagator Propagator to be used.
   */
  void SetPropagator(PndPropagator* propagator = nullptr);

